        {"name": "imsems10", "stem": "Being nonprejudiced is important to my self-concept.", "answers": [{"text": "Very Strongly Disagree", "value": 1}, {"text": "Strongly Disagree", "value": 2}, {"text": "Moderately Disagree", "value": 3}, {"text": "Slightly Disagree", "value": 4}, {"text": "Neither Agree Nor Disagree", "value": 5}, {"text": "Slightly Agree", "value": 6}, {"text": "Moderately Agree", "value": 7}, {"text": "Strongly Agree", "value": 8}, {"text": "Very Strongly Agree", "value": 9}]}
